CREATE TABLE ROL (
  ROIdRol INT NOT NULL PRIMARY KEY,
  ROName VARCHAR(50) NOT NULL,
  RODescripcion VARCHAR(150) NOT NULL
);

CREATE TABLE USERS (
  USId INT NOT NULL PRIMARY KEY,
  ROIdRol INT NULL,
  USName VARCHAR(80) NOT NULL,
  USLastName VARCHAR(80) NOT NULL,
  USEmail VARCHAR(120) NOT NULL,
  USPhone VARCHAR(20) NULL,
  USPassword VARCHAR(64) NOT NULL,
  USFregister DATE NULL,
  FOREIGN KEY (ROIdRol) REFERENCES ROL (ROIdRol)
);

CREATE TABLE MOTORCYCLES (
  MOIdMoto INT NOT NULL PRIMARY KEY,
  CUIdCustomer INT NULL,
  MOPlate VARCHAR(20) NULL,
  MOBrand VARCHAR(80) NOT NULL,
  MOModel VARCHAR(80) NOT NULL,
  MOYear VARCHAR(10) NOT NULL,
  MOColor VARCHAR(40) NOT NULL,
  MOCilindraje VARCHAR(20) NULL,
  MOVin VARCHAR(80) NULL,
  MOMiles VARCHAR(30) NULL,
  MOFRegister VARCHAR(20) NULL,
  MOChassis VARCHAR(80) NULL,
  MOState INT NULL,
  MOSerieInvoice VARCHAR(50) NOT NULL,
  MONumberInvoice VARCHAR(50) NOT NULL
);

CREATE TABLE CUSTOMER (
  CUIdCustomer INT NOT NULL PRIMARY KEY,
  CUName VARCHAR(80) NOT NULL,
  CULastName VARCHAR(80) NOT NULL,
  CUDPI VARCHAR(20) NOT NULL,
  CUNIT VARCHAR(20) NOT NULL,
  CUPhone VARCHAR(20) NOT NULL,
  CUMail VARCHAR(120) NOT NULL,
  CUAddress VARCHAR(150) NOT NULL,
  CUFregister DATE NULL,
  CUState INT NULL
);

CREATE TABLE STATE_PLATE (
  STIdState INT NOT NULL PRIMARY KEY,
  STState VARCHAR(100) NOT NULL
);

CREATE TABLE PROCESSING (
  PRIdProcess INT NOT NULL PRIMARY KEY,
  MOIdMoto INT NULL,
  STIdState INT NULL,
  PRFirstDate VARCHAR(20) NOT NULL,
  PRDateUpdate VARCHAR(20) NOT NULL,
  PRObservations VARCHAR(250) NOT NULL,
  FOREIGN KEY (MOIdMoto) REFERENCES MOTORCYCLES (MOIdMoto),
  FOREIGN KEY (STIdState) REFERENCES STATE_PLATE (STIdState)
);

CREATE TABLE MAINTENANCE (
  MAMaintenance INT NOT NULL PRIMARY KEY,
  MOIdMoto INT NULL,
  USId INT NULL,
  MADate DATE NOT NULL,
  MAMiles VARCHAR(30) NULL,
  MAObservations VARCHAR(250) NULL,
  MANextMiles VARCHAR(30) NULL,
  MANextDate VARCHAR(30) NULL,
  FOREIGN KEY (MOIdMoto) REFERENCES MOTORCYCLES (MOIdMoto),
  FOREIGN KEY (USId) REFERENCES USERS (USId)
);

CREATE TABLE SERVICES (
  SEIdService INT NOT NULL PRIMARY KEY,
  SEName VARCHAR(100) NOT NULL,
  SEDescription VARCHAR(250) NOT NULL,
  SEMilesRecom VARCHAR(30) NULL,
  SETimeRecom VARCHAR(30) NULL,
  SEPriceRef DECIMAL(10,2) NULL,
  SEState INT NULL,
  SEDetails VARCHAR(250) NULL
);

CREATE TABLE DETAIL_MAINTENANCE (
  DMIdDetail INT NOT NULL PRIMARY KEY,
  MAMaintenance INT NULL,
  SEIdService INT NULL,
  SEAmount DECIMAL(10,2) NULL,
  FOREIGN KEY (MAMaintenance) REFERENCES MAINTENANCE (MAMaintenance),
  FOREIGN KEY (SEIdService) REFERENCES SERVICES (SEIdService)
);

CREATE TABLE SPARE_PARTS (
  SPId INT NOT NULL PRIMARY KEY,
  SPNname VARCHAR(100) NOT NULL,
  SPBrand VARCHAR(100) NOT NULL,
  SPDescription VARCHAR(250) NOT NULL
);

CREATE TABLE REMINDER (
  REIdReminder INT NOT NULL PRIMARY KEY,
  MAMaintenance INT NULL,
  RETitle VARCHAR(100) NOT NULL,
  REDescription VARCHAR(250) NOT NULL,
  REDateProgram VARCHAR(30) NOT NULL,
  REType VARCHAR(50) NOT NULL,
  REState INT NULL,
  REFSend VARCHAR(30) NOT NULL,
  FOREIGN KEY (MAMaintenance) REFERENCES MAINTENANCE (MAMaintenance)
);

